import{_ as e,o as t,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"幅相分解","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/modules/magphase_split/index.md","filePath":"v0.3.0-alpha/modules/magphase_split/index.md"}'),r={name:"v0.3.0-alpha/modules/magphase_split/index.md"};function i(l,a,h,n,p,c){return t(),d("div",null,[...a[0]||(a[0]=[o('<h1 id="幅相分解" tabindex="-1">幅相分解 <a class="header-anchor" href="#幅相分解" aria-label="Permalink to &quot;幅相分解&quot;">​</a></h1><p>适用：v0.3.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>magphase_split</code> · 模块定义版本：1</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>将一个复数样本拆成幅度和相位两路实数输出。若输入为 <code>I+jQ</code>，幅度为 <code>sqrt(I²+Q²)</code>，相位是该复数在复平面上的主值辐角。</p><p>幅度使用归一化信号幅度，相位使用弧度 rad。它与 I/Q 分解不同：I、Q 是带正负号的直角坐标，幅度、相位是同一样本的极坐标表示。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>调频.out → 幅相分解.in</code>。从 <code>magnitude</code> 观察包络，从 <code>phase</code> 观察相位；两路都对应同一个输入样本，采样率不变。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（复数输入）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>magnitude</code>（幅度）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>phase</code>（相位）</td><td><code>numeric_f64</code></td><td>rad；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>本模块没有可调参数，当前只接收标量复数流，每个输入 item 产生一个幅度 item 和一个相位 item。</p><p>相位是主值，转过边界时会绕回，并未自动展开为连续累计相位。零幅度样本的原生相位输出为 0，但零向量没有确定的物理相位，不能把这个 0 当作有效方向。</p><p>此模块没有可编辑计算参数。</p><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>本模块没有在线系数。输出随实际输入变化；更换接线或输入结构后，停止并重新准备工程。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="调频、幅相、正交解调与二值-bpsk-映射" tabindex="-1">调频、幅相、正交解调与二值 BPSK 映射 <a class="header-anchor" href="#调频、幅相、正交解调与二值-bpsk-映射" aria-label="Permalink to &quot;调频、幅相、正交解调与二值 BPSK 映射&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/modulation-chain.cnsproj" download>下载 modulation-chain.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>调频、幅相、正交解调与二值 BPSK 映射</p><ul><li>Fs=4096，常量 1 经 sensitivity=π/8 调频得到 +256 Hz、模长 1 的复相量，首项先累加。幅相输出主值相位；gain=8/π 解调首项为 0、后续约 1。二值判决对零和正值均输出索引 1，按生产 BPSK 点表映射。码元 OUT 固定 M2，不生成模拟幅度频谱。</li></ul><p>调频与判决示例中，采样率为 4096 Hz，常量 1 经灵敏度 π/8 的调频器产生正向旋转的复数信号。分别选择本模块的两路输出：幅度应约为 1，相位应随采样推进并在主值边界绕回。</p><p>观察 <code>phase</code> 的时域输出可以看到绕回；观察调频器复数输出的频谱，则应看到约 +256 Hz 的谱峰。相位曲线的跳变不表示复数信号突然改变了包络。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>相位突然从一端跳到另一端，是数据断了吗？</strong> 先检查是否为主值绕回。连续旋转的复数信号也会出现这种相位显示；本模块不做相位展开。</p><p><strong>幅度为什么没有 I、Q 的正负号？</strong> 幅度是复数到原点的距离，方向由相位表示。需要分别保留两个有符号分量时，使用 I/Q 分解。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/08-fm/">08 从数值到调频再解调</a></li></ul>',29)])])}const u=e(r,[["render",i]]);export{m as __pageData,u as default};
